/* machine-generated by m2c: a starting point, not a match */
#ifndef M2C_DEFINES
#define M2C_DEFINES
typedef s32 M2C_UNK;
typedef s8 M2C_UNK8;
typedef s16 M2C_UNK16;
typedef s32 M2C_UNK32;
#define M2C_FIELD(expr, type_ptr, offset) (*(type_ptr)((s8 *)(expr) + (offset)))
#define M2C_BITWISE(type, expr) ((type)(expr))
#define M2C_ERROR(desc) (0)
#define M2C_CARRY 0
#define M2C_OVERFLOW(a) (0)
#endif

M2C_UNK waitForGfxMessage();                            /* extern */
M2C_UNK osRecvMesg(M2C_UNK *, M2C_UNK, M2C_UNK);    /* extern */
extern s16 gFramesQueuedCount;
extern s16 gFramesCompletedCount;
extern M2C_UNK gFrameDoneMsgQueue;

/* Blocks until every queued frame has been completed, consuming one message per frame. */ void waitForPendingFrames(void) {
    s16 completed;

    if (gFramesQueuedCount != gFramesCompletedCount) {
        do {
            waitForGfxMessage();
            osRecvMesg(&gFrameDoneMsgQueue, 0, 1);
            completed = (u16) gFramesCompletedCount + 1;
            gFramesCompletedCount = completed;
        } while (gFramesQueuedCount != completed);
    }
}
